+    codec_ctx->channel_layout = AV_CH_FRONT_LEFT | AV_CH_FRONT_RIGHT;
+
+    // allocate buffer for input samples
+    uint8_t* buffer = (uint8_t*)av_malloc(max_buffer_size);
+    assert(buffer);
